def read(n):return pd.read_csv(OUT/n).fillna('')
def val(x):
 if isinstance(x,(float,np.floating)):
  if not np.isfinite(x):return ''
  return f'{x:.6g}'
 return str(x).replace('|','/').replace('\n',' ')
def table(name,d):
 rows('report_tables/'+name+'.csv',d)
 return '\n'.join(['| '+' | '.join(map(str,d.columns))+' |','| '+' | '.join(['---']*len(d.columns))+' |']+['| '+' | '.join(val(x) for x in r)+' |' for r in d.itertuples(index=False,name=None)])+'\n'
def link(label,url):return f'[{label}]({url})'
def citation(r):return link(str(r.source_id),str(r.source_url))
